package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PlusToolsTest {
 Activity a;@Before public void setup(){WorkspaceEpoch.value=0;WorkspaceEpoch.restoring=false;a=Robolectric.buildActivity(Activity.class).setup().get();a.setContentView(new LinearLayout(a));} @After public void close(){UiDialog.dismissAll(a);UiPanel.dismissAll(a);SleepTimer.cancel(a);SleepTimer.unwatch(a);a.finish();}
 @Test public void multipleSelectionStaysOpenAndUpdatesTheCallerArray(){boolean[] chosen={false,true,false};UiDialog dialog=new UiDialog.Builder(a).setTitle("Caderno").setMultiChoiceItems(new String[]{"Um","Dois","Três"},chosen,(d,n,on)->{}).setPositiveButton("Guardar",null).create();dialog.show();ListView list=dialog.getListView();assertNotNull(list);assertEquals(3,list.getAdapter().getCount());list.performItemClick(list.getAdapter().getView(0,null,list),0,0);assertTrue(chosen[0]);assertTrue(chosen[1]);assertTrue(dialog.isShowing());list.performItemClick(list.getAdapter().getView(1,null,list),1,1);assertFalse(chosen[1]);}
 @Test public void builderCancelCallbackIsNotLostByTheCustomDialog(){AtomicBoolean cancelled=new AtomicBoolean();UiDialog dialog=new UiDialog.Builder(a).setTitle("Verificar").setMessage("Teste").setOnCancelListener(d->cancelled.set(true)).create();dialog.show();dialog.cancel();shadowOf(Looper.getMainLooper()).idle();assertTrue(cancelled.get());}
 @Test public void lowMemoryPolicyAndExplicitOverridesWork(){assertTrue(PerformanceMode.automatic(false,128,268435456));assertTrue(PerformanceMode.automatic(false,512,134217728));assertTrue(PerformanceMode.automatic(true,512,1073741824));assertFalse(PerformanceMode.automatic(false,512,1073741824));PerformanceMode.choose(a,1);assertTrue(PerformanceMode.light(a));assertTrue(PerformanceMode.thumbnailCache(a)<=1572864);PerformanceMode.choose(a,2);assertFalse(PerformanceMode.light(a));}
 @Test public void collectionsAndTopicsFollowAHashAndQueriesRemainBounded()throws Exception{String hash=String.join("",Collections.nCopies(64,"a"));try(PlusStore db=new PlusStore(a)){long id=BookCategories.collection(db,"Leitura pessoal");assertEquals(id,BookCategories.collection(db,"Leitura pessoal"));db.save("book_collections",StudyStore.values("hash",hash,"collection",id));db.save("book_meta",StudyStore.values("hash",hash,"topic","Teologia","series","Estudo 1"));assertEquals(Collections.singleton(hash),db.hashes("collection",""+id));assertEquals(Collections.singleton(hash),db.hashes("topic","Teologia"));assertTrue(db.hashes("topic","' OR 1=1 --").isEmpty());}assertEquals("0=1",PlusStore.inHashes(Collections.singleton("malicious'")));}
 @Test public void sleepTimerFiresOnceWithTheScreenIndependentMainClock(){AtomicInteger stops=new AtomicInteger();SleepTimer.watch(a,stops::incrementAndGet);SleepTimer.arm(a,1);shadowOf(Looper.getMainLooper()).idleFor(59,TimeUnit.SECONDS);assertEquals(0,stops.get());shadowOf(Looper.getMainLooper()).idleFor(1,TimeUnit.SECONDS);assertEquals(1,stops.get());assertEquals(-1,SleepTimer.remaining(a));shadowOf(Looper.getMainLooper()).idleFor(2,TimeUnit.MINUTES);assertEquals(1,stops.get());}
 @Test public void sleepChapterBoundaryMatchesOnlyTheChosenDocument(){AtomicInteger stops=new AtomicInteger();SleepTimer.watch(a,stops::incrementAndGet);SleepTimer.end(a,"content://book/one",2,0);assertFalse(SleepTimer.boundary(a,"content://book/two",2));assertFalse(SleepTimer.boundary(a,"content://book/one",1));assertEquals(0,stops.get());assertTrue(SleepTimer.boundary(a,"content://book/one",2));assertEquals(1,stops.get());}
 @Test public void toolsScreenOffersAllEntryPointsAndCanRenderAtPhoneWidth()throws Exception{org.robolectric.android.controller.ActivityController<ToolsActivity> controller=Robolectric.buildActivity(ToolsActivity.class).create().start().resume().visible();try{ToolsActivity tools=controller.get();String labels=BooksToolsTest.labels(tools.content);for(String expected:new String[]{"Colecções","Bíblias importadas","Desempenho","Dicionário de pronúncia","Dados de OCR","Caderno de revisão em PDF","Cópia e recuperação"})assertTrue(expected,labels.contains(expected));android.view.View root=tools.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(640,View.MeasureSpec.EXACTLY));root.layout(0,0,320,640);android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(320,640,android.graphics.Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(image));try(java.io.FileOutputStream out=new java.io.FileOutputStream(System.getProperty("seeky.screenshot")+"-plus-tools.png")){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}finally{controller.pause().stop().destroy();}}
 @Test public void criticalRestoreDialogCannotBeCancelledButCanFinish(){AtomicBoolean cancelled=new AtomicBoolean();UiDialog dialog=new UiDialog.Builder(a).setTitle("Recuperar biblioteca").setNegativeButton("Cancelar",(d,w)->cancelled.set(true)).setOnCancelListener(d->cancelled.set(true)).create();dialog.show();dialog.lock();dialog.getButton(-2).performClick();dialog.cancel();shadowOf(Looper.getMainLooper()).idle();assertTrue(dialog.isShowing());assertFalse(cancelled.get());assertFalse(dialog.getButton(-2).isEnabled());dialog.dismiss();assertFalse(dialog.isShowing());}
 @Test public void newToolControlsAndProgressHaveEnglishTranslations(){a.getSharedPreferences("seeky",0).edit().putString("language","en").apply();org.robolectric.android.controller.ActivityController<ToolsActivity> controller=Robolectric.buildActivity(ToolsActivity.class).create().start().resume().visible();try{String labels=BooksToolsTest.labels(controller.get().content);for(String expected:new String[]{"Imported Bibles","Pronunciation dictionary","OCR language data","PDF revision notebook","Backup and restore"})assertTrue(expected,labels.contains(expected));assertEquals("Saving file 23 / 1200",AppLanguage.text(a,"A guardar ficheiro 23 / 1200"));assertEquals("30 minutes",AppLanguage.text(a,"30 minutos"));}finally{controller.pause().stop().destroy();}}

 @Test public void revisionNotebookSelectsOnlyTheChosenModule()throws Exception{long module,other;try(StudyStore db=new StudyStore(a)){module=db.save("subjects",0,StudyStore.values("title","Física","color",0xff6d4aff,"created",1));other=db.save("subjects",0,StudyStore.values("title","História","color",0xff6d4aff,"created",1));db.save("notes",0,StudyStore.values("subject",module,"title","Nota de Física","body","Uma explicação.","created",1,"updated",1));db.save("notes",0,StudyStore.values("subject",other,"title","Nota de História","body","Outra explicação.","created",1,"updated",1));db.save("cards",0,StudyStore.values("subject",module,"front","Uma pergunta de Física?","back","Uma resposta.","due",1,"updated",1));}RevisionNotebook notebook=new RevisionNotebook(a,"",0,module,"Física");java.util.List<RevisionNotebook.Choice> selected=notebook.choices();assertEquals(2,selected.size());assertTrue(selected.stream().allMatch(c->c.title.contains("Física")));assertTrue(notebook.body(selected.get(0)).contains("Uma explicação"));ToolsActivity.revision(a,module,"Física");Intent launch=shadowOf(a).getNextStartedActivity();assertEquals(module,launch.getLongExtra("subject",0));assertEquals("revision",launch.getStringExtra("page"));}

}
